struct Position: CustomStringConvertible {
    let file: String, line: Int;
    var description: String {
        "\(file):\(line)"
    }
}
struct Diagnostic {
    let position: Position, kind: String, message: String
}
struct PPError: Error {
    let message: String;
    init(_ message: String) {
        self.message = message
    }
}
func builtin(_ name: String) -> Bool {
    ["__LINE__", "__FILE__", "__COUNTER__"].contains(name)
}
final class Macro {
    let name: String, parameters: [String]?, variadic: Bool, replacement: [Token], position: Position, main: Bool
    var expanded = 0, tested = 0
    init(_ name: String, _ parameters: [String]?, _ variadic: Bool, _ replacement: [Token], _ position: Position, _ main: Bool) {
        self.name = name;
        self.parameters = parameters;
        self.variadic = variadic;
        self.replacement = replacement;
        self.position = position;
        self.main = main
    }
    var signature: String {
        guard var parameters else {
            return name
        };
        if variadic {
            parameters[parameters.count - 1] = "..."
        };
        return name + "(" + parameters.joined(separator: ", ") + ")"
    }
    var definition: String {
        "#define " + signature + (replacement.isEmpty ? "" : " " + Lexer.render(replacement))
    }
    func identical(_ other: Macro) -> Bool {
        parameters == other.parameters && variadic == other.variadic && replacement.count == other.replacement.count && zip(replacement, other.replacement).allSatisfy {
            a, b in a.text == b.text && a.space == b.space
        }
    }
}
enum Definitions {
    static func name(_ tokens: [Token], _ directive: String) throws -> String {
        guard let token = tokens.first else {
            throw PPError("no macro name given in #\(directive) directive")
        }
        if token.kind != "identifier" {
            throw PPError("macro names must be identifiers")
        }
        if token.text == "defined" {
            throw PPError("\"defined\" cannot be used as a macro name")
        }
        if builtin(token.text) {
            throw PPError("cannot \(directive == "define" ? "redefine" : "undefine") builtin macro \"\(token.text)\"")
        };
        return token.text
    }
    static func parse(_ tokens: [Token], _ position: Position, _ main: Bool) throws -> Macro {
        let name = try self.name(tokens, "define"), vaError = "\"__VA_ARGS__\" can only appear in the expansion of a variadic macro"
        if name == "__VA_ARGS__" {
            throw PPError(vaError)
        }
        var i = 1, parameters: [String]?, variadic = false
        if tokens.count > 1 && tokens[1].text == "(" && !tokens[1].space {
            i = 2;
            var names: [String] = []
            if i < tokens.count && tokens[i].text == ")" {
                i += 1
            }
            else {
                while true {
                    guard i < tokens.count else {
                        throw PPError("missing ')' in macro parameter list")
                    };
                    let token = tokens[i]
                    if token.text == "..." {
                        variadic = true;
                        names.append("__VA_ARGS__")
                    }
                    else if token.kind == "identifier" {
                        if token.text == "__VA_ARGS__" {
                            throw PPError(vaError)
                        };
                        if names.contains(token.text) {
                            throw PPError("duplicate macro parameter \"\(token.text)\"")
                        };
                        names.append(token.text)
                    }
                    else {
                        throw PPError("expected parameter name, found \"\(token.text)\"")
                    }
                    i += 1;
                    guard i < tokens.count else {
                        throw PPError("missing ')' in macro parameter list")
                    }
                    if tokens[i].text == ")" {
                        i += 1;
                        break
                    }
                    if variadic {
                        throw PPError("expected ')' after \"...\", found \"\(tokens[i].text)\"")
                    }
                    if tokens[i].text != "," {
                        throw PPError("expected ',' or ')', found \"\(tokens[i].text)\"")
                    };
                    i += 1
                }
            };
            parameters = names
        }
        var replacement = Array(tokens.dropFirst(i));
        if !replacement.isEmpty {
            replacement[0].space = false
        }
        if replacement.first?.text == "##" || replacement.last?.text == "##" {
            throw PPError("'##' cannot appear at either end of a macro expansion")
        }
        for (i, token) in replacement.enumerated() {
            if token.kind == "identifier" && token.text == "__VA_ARGS__" && !variadic {
                throw PPError(vaError)
            }
            if token.text == "#", let names = parameters {
                if i + 1 == replacement.count || replacement[i + 1].kind != "identifier" || !names.contains(replacement[i + 1].text) {
                    throw PPError("'#' is not followed by a macro parameter")
                }
            }
        };
        return Macro(name, parameters, variadic, replacement, position, main)
    }
}

enum ReplacementItem {
    case sequence([Token]), paste(Token)
}
final class Expander {
    var table: [String: Macro] = [:], diagnostics: [Diagnostic] = [], uses = ["__COUNTER__": 0, "__FILE__": 0, "__LINE__": 0], counter = 0
    func diagnostic(_ position: Position, _ kind: String, _ message: String) {
        diagnostics.append(Diagnostic(position: position, kind: kind, message: message))
    }
    func error(_ token: Token, _ file: String, _ offset: Int, _ message: String) {
        diagnostic(Position(file: file, line: token.line + offset), "error", message)
    }
    func expand(_ tokens: [Token], _ file: String, _ offset: Int) -> [Token] {
        var input = Array(tokens.reversed()), result: [Token] = []
        while let token = input.popLast() {
            if token.kind != "identifier" || token.hide.contains(token.text) {
                result.append(token);
                continue
            }
            if builtin(token.text) {
                uses[token.text, default: 0] += 1
                let kind: String, text: String
                switch token.text {
                    case "__LINE__": kind = "number";
                    text = String(token.line + offset);
                    case "__FILE__": kind = "string";
                    text = "\"" + file + "\"";
                    default: kind = "number";
                    text = String(counter);
                    counter += 1
                }
                result.append(Token(kind, text, token.line, token.space));
                continue
            }
            guard let definition = table[token.text] else {
                result.append(token);
                continue
            }
            var hide = token.hide, arguments: [[Token]] = []
            if definition.parameters != nil {
                if input.last?.text != "(" {
                    result.append(token);
                    continue
                }
                guard let (collected, consumed, closing) = collect(definition, input, token, file, offset) else {
                    result.append(token);
                    continue
                }
                arguments = collected;
                input.removeLast(consumed);
                hide = token.hide.intersection(closing.hide)
            }
            hide.insert(definition.name)
            let replacement = substitute(definition, arguments, token, hide, file, offset);
            definition.expanded += 1
            if replacement.isEmpty && token.space && !input.isEmpty {
                input[input.count - 1].space = true
            }
            input.append(contentsOf: replacement.reversed())
        };
        return result
    }
    func collect(_ definition: Macro, _ reversed: [Token], _ token: Token, _ file: String, _ offset: Int) -> ([[Token]], Int, Token)? {
        var arguments: [[Token]] = [[]], separators: [Token] = [], depth = 0, closing: (Int, Token)?
        let input = reversed.reversed()
        for (i, current) in input.enumerated().dropFirst() {
            if current.text == ")" && depth == 0 {
                closing = (i, current);
                break
            }
            if current.text == "," && depth == 0 {
                separators.append(current);
                arguments.append([])
            }
            else {
                if current.text == "(" {
                    depth += 1
                } else if current.text == ")" {
                    depth -= 1
                };
                arguments[arguments.count - 1].append(current)
            }
        }
        guard let (end, close) = closing else {
            error(token, file, offset, "unterminated argument list invoking macro \"\(definition.name)\"");
            return nil
        }
        let k = arguments.count, n = definition.parameters!.count - (definition.variadic ? 1 : 0), emptyZero = !definition.variadic && n == 0 && k == 1 && arguments[0].isEmpty
        let message: String?
        if !definition.variadic && n == 0 && !emptyZero {
            message = "macro \"\(definition.name)\" passed \(k) arguments, but takes just 0"
        }
        else if k < n {
            message = "macro \"\(definition.name)\" requires \(n) arguments, but only \(k) given"
        }
        else if k > n && !definition.variadic {
            message = "macro \"\(definition.name)\" passed \(k) arguments, but takes just \(n)"
        }
        else {
            message = nil
        }
        if let message {
            error(token, file, offset, message);
            return nil
        }
        if definition.variadic {
            var variable: [Token] = []
            for i in n..<k {
                if i > n {
                    variable.append(separators[i - 1])
                };
                variable += arguments[i]
            };
            arguments = Array(arguments.prefix(n));
            arguments.append(variable)
        } else if emptyZero {
            arguments = []
        };
        return (arguments, end + 1, close)
    }
    func stringize(_ tokens: [Token], _ template: Token) -> Token {
        var text = ""
        for (i, token) in tokens.enumerated() {
            if i > 0 && token.space {
                text += " "
            }
            if token.kind == "string" || token.kind == "character" {
                for c in token.text {
                    if c == "\\" || c == "\"" {
                        text += "\\"
                    };
                    text.append(c)
                }
            } else {
                text += token.text
            }
        };
        return Token("string", "\"" + text + "\"", template.line, template.space)
    }
    func paste(_ left: Token, _ originalRight: Token, _ invocation: Token, _ file: String, _ offset: Int) -> [Token] {
        var right = originalRight
        if left.kind == "placemarker" {
            right.space = left.space;
            return [right]
        };
        if right.kind == "placemarker" {
            return [left]
        }
        let text = left.text + right.text
        if let kind = Lexer.single(text) {
            var token = Token(kind, text, left.line, left.space);
            token.hide = left.hide.intersection(right.hide);
            return [token]
        }
        error(invocation, file, offset, "pasting \"\(left.text)\" and \"\(right.text)\" does not give a valid preprocessing token");
        right.space = false;
        return [left, right]
    }
    func substitute(_ definition: Macro, _ arguments: [[Token]], _ invocation: Token, _ hide: Set<String>, _ file: String, _ offset: Int) -> [Token] {
        let names = definition.parameters ?? [], replacement = definition.replacement
        var expanded: [Int: [Token]] = [:], items: [ReplacementItem] = [], i = 0
        while i < replacement.count {
            let token = replacement[i]
            if token.text == "#" && definition.parameters != nil {
                let parameter = names.firstIndex(of: replacement[i + 1].text)!;
                items.append(.sequence([stringize(arguments[parameter], token)]));
                i += 2;
                continue
            }
            if token.text == "##" {
                items.append(.paste(token))
            }
            else if token.kind == "identifier", let parameter = names.firstIndex(of: token.text) {
                let raw = i > 0 && replacement[i - 1].text == "##" || i + 1 < replacement.count && replacement[i + 1].text == "##"
                var sequence: [Token]
                if raw {
                    sequence = arguments[parameter]
                }
                else {
                    if expanded[parameter] == nil {
                        expanded[parameter] = expand(arguments[parameter], file, offset)
                    };
                    sequence = expanded[parameter]!
                }
                if !sequence.isEmpty {
                    sequence[0].space = token.space
                } else {
                    sequence = [Token("placemarker", "", token.line, token.space)]
                };
                items.append(.sequence(sequence))
            } else {
                items.append(.sequence([token]))
            };
            i += 1
        }
        var output: [Token] = [];
        i = 0
        while i < items.count {
            switch items[i] {
                case .sequence(let sequence): output += sequence
                case .paste:
                let left = output.removeLast();
                var right: [Token]
                switch items[i + 1] {
                    case .sequence(let sequence): right = sequence;
                    case .paste(let token): right = [token]
                }
                let first = right.removeFirst();
                output += paste(left, first, invocation, file, offset);
                output += right;
                i += 1
            };
            i += 1
        }
        var result: [Token] = [], space = false
        for var token in output {
            if token.kind == "placemarker" {
                space = space || token.space;
                continue
            }
            if space {
                token.space = true;
                space = false
            };
            token.line = invocation.line;
            token.hide.formUnion(hide);
            result.append(token)
        };
        if !result.isEmpty {
            result[0].space = invocation.space
        };
        return result
    }
}

indirect enum PPExpression {
    case value(Int), name(String), unary(String, PPExpression), binary(String, PPExpression, PPExpression), conditional(PPExpression, PPExpression, PPExpression)
}
final class ExpressionParser {
    let tokens: [Token];
    var index = 0
    init(_ tokens: [Token]) {
        self.tokens = tokens
    };
    var text: String {
        index < tokens.count ? tokens[index].text : ""
    }
    func priority(_ op: String) -> Int {
        switch op {
            case "||": return 1;
            case "&&": return 2;
            case "|": return 3;
            case "^": return 4;
            case "&": return 5;
            case "==", "!=": return 6;
            case "<", ">", "<=", ">=": return 7;
            case "<<", ">>": return 8;
            case "+", "-": return 9;
            case "*", "/", "%": return 10;
            default: return 0
        }
    }
    func expression() throws -> PPExpression {
        let left = try binary(1)
        if text == "?" {
            index += 1;
            let yes = try expression();
            if text != ":" {
                throw PPError("'?' without following ':'")
            };
            index += 1;
            return .conditional(left, yes, try expression())
        };
        return left
    }
    func binary(_ minimum: Int) throws -> PPExpression {
        var left = try unary()
        while priority(text) >= minimum {
            let op = text;
            index += 1;
            left = .binary(op, left, try binary(priority(op) + 1))
        };
        return left
    }
    func unary() throws -> PPExpression {
        if ["+", "-", "!", "~"].contains(text) {
            let op = text;
            index += 1;
            return .unary(op, try unary())
        }
        guard index < tokens.count else {
            throw PPError("expected value at end of expression")
        };
        let token = tokens[index];
        index += 1
        if token.kind == "number" || token.kind == "character" {
            return .value(try Self.constant(token))
        }
        if token.kind == "identifier" {
            return .name(token.text)
        }
        if token.text == "(" {
            let value = try expression();
            if text != ")" {
                throw PPError("missing ')' in expression")
            };
            index += 1;
            return value
        };
        throw PPError("expected value before \"\(token.text)\"")
    }
    static func constant(_ token: Token) throws -> Int {
        let original = token.text
        if token.kind == "character" {
            let body = Array(original.utf8.dropFirst().dropLast())
            if body.count == 1 && body[0] != 39 && body[0] != 92 {
                return Int(body[0])
            }
            if body.count == 2 && body[0] == 92, let value = [UInt8(110): 10, 116: 9, 92: 92, 39: 39, 34: 34, 48: 0][body[1]] {
                return value
            };
            throw PPError("invalid character constant \(original)")
        }
        var body = original
        for suffix in ["ll", "LL", "l", "L"] where body.count > suffix.count && body.hasSuffix(suffix) {
            body = String(body.dropLast(suffix.count));
            break
        }
        let base: Int, digits: String
        if body.hasPrefix("0x") || body.hasPrefix("0X") {
            base = 16;
            digits = String(body.dropFirst(2))
        } else if body.first == "0" {
            base = 8;
            digits = body
        } else {
            base = 10;
            digits = body
        }
        let valid = !digits.isEmpty && digits.utf8.allSatisfy {
            c in base == 16 ? (48...57).contains(c) || (65...70).contains(c) || (97...102).contains(c) : base == 8 ? (48...55).contains(c) : (48...57).contains(c)
        }
        if valid, let value = Int(digits, radix: base) {
            return value
        };
        throw PPError("invalid integer constant \"\(original)\"")
    }
    static func evaluate(_ expression: PPExpression, _ diagnostics: inout [(String, String)]) throws -> Int {
        switch expression {
            case .value(let value): return value
            case .name(let name): diagnostics.append(("warning", "identifier \"\(name)\" evaluates to 0"));
            return 0
            case .unary(let op, let operand): let value = try evaluate(operand, &diagnostics);
            switch op {
                case "+": return value;
                case "-": return -value;
                case "!": return value == 0 ? 1 : 0;
                default: return -value - 1
            }
            case .conditional(let condition, let yes, let no): let value = try evaluate(condition, &diagnostics);
            return try evaluate(value != 0 ? yes : no, &diagnostics)
            case .binary(let op, let left, let right):
            let a = try evaluate(left, &diagnostics);
            if op == "&&" && a == 0 {
                return 0
            };
            if op == "||" && a != 0 {
                return 1
            };
            let b = try evaluate(right, &diagnostics)
            if (op == "/" || op == "%") && b == 0 {
                throw PPError("division by zero in #if")
            }
            switch op {
                case "+": return a + b;
                case "-": return a - b;
                case "*": return a * b;
                case "/": return a / b;
                case "%": return a % b;
                case "<<": return a << b;
                case ">>": return a >> b;
                case "&": return a & b;
                case "|": return a | b;
                case "^": return a ^ b;
                case "&&", "||": return b == 0 ? 0 : 1;
                case "<": return a < b ? 1 : 0;
                case ">": return a > b ? 1 : 0;
                case "<=": return a <= b ? 1 : 0;
                case ">=": return a >= b ? 1 : 0;
                case "==": return a == b ? 1 : 0;
                default: return a != b ? 1 : 0
            }
        }
    }
    static func test(_ tokens: [Token], _ directive: String) -> (Int?, [(String, String)]) {
        let parser = ExpressionParser(tokens);
        var diagnostics: [(String, String)] = []
        do {
            if tokens.isEmpty {
                throw PPError("#\(directive) with no expression")
            };
            let expression = try parser.expression()
            if parser.index != tokens.count {
                throw PPError("missing binary operator before \"\(tokens[parser.index].text)\"")
            };
            return (try evaluate(expression, &diagnostics), diagnostics)
        } catch let error as PPError {
            diagnostics.append(("error", error.message));
            return (nil, diagnostics)
        } catch {
            preconditionFailure()
        }
    }
}

import Foundation
final class SourceFile {
    let lines: [LogicalLine], physicalLines: Int, guardName: String?
    var entered = 0, skipped = 0, output = 0, skippedLines = 0, once = false
    init(_ source: String) {
        lines = Lexer.lex(source);
        physicalLines = source.utf8.filter {
            $0 == 10
        }.count;
        guardName = IncludeManager.guardName(lines)
    }
}
final class IncludeManager {
    var files: [String: SourceFile] = [:], order: [String] = []
    static func search(_ name: String, _ quoted: Bool) -> String? {
        if quoted && FileManager.default.fileExists(atPath: "input/" + name) {
            return name
        }
        let path = "include/" + name;
        return FileManager.default.fileExists(atPath: "input/" + path) ? path : nil
    }
    static func guardName(_ original: [LogicalLine]) -> String? {
        let lines = original.filter {
            !$0.tokens.isEmpty
        };
        guard let first = lines.first?.tokens, let last = lines.last?.tokens, first.count == 3, first[0].text == "#", first[1].text == "ifndef", first[2].kind == "identifier", last.count == 2, last[0].text == "#", last[1].text == "endif" else {
            return nil
        }
        var depth = 0
        for (i, line) in lines.enumerated() {
            let tokens = line.tokens, directive = tokens.count >= 2 && tokens[0].text == "#" && tokens[1].kind == "identifier" ? tokens[1].text : ""
            if depth == 1 && ["elif", "elifdef", "elifndef", "else"].contains(directive) {
                return nil
            }
            if ["if", "ifdef", "ifndef"].contains(directive) {
                depth += 1
            } else if directive == "endif" {
                depth -= 1
            }
            if depth == 0 && i + 1 != lines.count {
                return nil
            }
        };
        return depth == 0 ? first[2].text : nil
    }
    func enter(_ path: String) -> SourceFile {
        if files[path] == nil {
            files[path] = SourceFile(try! String(contentsOfFile: "input/" + path, encoding: .ascii));
            order.append(path)
        };
        let file = files[path]!;
        file.entered += 1;
        return file
    }
}

struct Token {
    var kind: String, text: String, line: Int, space: Bool, hide: Set<String> = []
    init(_ kind: String, _ text: String, _ line: Int, _ space: Bool) {
        self.kind = kind;
        self.text = text;
        self.line = line;
        self.space = space
    }
}
struct LogicalLine {
    let tokens: [Token], start: Int, end: Int
}
enum Lexer {
    static func one(_ bytes: [UInt8], _ start: Int = 0, _ header: Bool = false) -> (String, Int) {
        if start == bytes.count {
            return ("other", 0)
        };
        let c = bytes[start]
        func letter(_ c: UInt8) -> Bool {
            (65...90).contains(c) || (97...122).contains(c)
        }
        func digit(_ c: UInt8) -> Bool {
            (48...57).contains(c)
        }
        if header && c == 60 {
            var end = start + 1;
            while end < bytes.count && bytes[end] != 10 && bytes[end] != 62 {
                end += 1
            };
            if end < bytes.count && bytes[end] == 62 {
                return ("header", end - start + 1)
            }
        }
        if letter(c) || c == 95 {
            var n = start + 1;
            while n < bytes.count && (letter(bytes[n]) || digit(bytes[n]) || bytes[n] == 95) {
                n += 1
            };
            return ("identifier", n - start)
        }
        if digit(c) || c == 46 && start + 1 < bytes.count && digit(bytes[start + 1]) {
            var n = start + 1
            while n < bytes.count {
                if Array("eEpP".utf8).contains(bytes[n]) && n + 1 < bytes.count && [UInt8(43), 45].contains(bytes[n + 1]) {
                    n += 2
                }
                else if letter(bytes[n]) || digit(bytes[n]) || bytes[n] == 95 || bytes[n] == 46 {
                    n += 1
                } else {
                    break
                }
            };
            return ("number", n - start)
        }
        if c == 39 || c == 34 {
            var n = start + 1
            while n < bytes.count && bytes[n] != 10 {
                if bytes[n] == c {
                    return (c == 39 ? "character" : "string", n - start + 1)
                };
                if bytes[n] == 92 && n + 1 < bytes.count && bytes[n + 1] != 10 {
                    n += 2
                } else {
                    n += 1
                }
            }
        }
        for punct in ["...", "<<=", ">>=", "->", "++", "--", "<<", ">>", "<=", ">=", "==", "!=", "&&", "||", "*=", "/=", "%=", "+=", "-=", "&=", "^=", "|=", "##"] {
            let pattern = Array(punct.utf8);
            if start + pattern.count <= bytes.count && Array(bytes[start..<(start + pattern.count)]) == pattern {
                return ("punctuator", pattern.count)
            }
        };
        return (Array("[](){}.&*+-~!/%<>^|?:;=,#".utf8).contains(c) ? "punctuator" : "other", 1)
    }
    static func single(_ text: String) -> String? {
        let bytes = Array(text.utf8);
        if bytes.isEmpty || bytes.count > 1 && bytes[0] == 47 && [UInt8(47), 42].contains(bytes[1]) {
            return nil
        };
        let (kind, n) = one(bytes);
        return n == bytes.count ? kind : nil
    }
    static func separator(_ left: String, _ right: String) -> Bool {
        left == "/" && (right.first == "/" || right.first == "*") || one(Array((left + right).utf8)).1 != left.utf8.count
    }
    static func render(_ tokens: [Token], _ output: Bool = false) -> String {
        var text = ""
        for (i, token) in tokens.enumerated() {
            if i > 0 && (token.space || output && separator(tokens[i - 1].text, token.text)) {
                text += " "
            };
            text += token.text
        };
        return text
    }
    static func lex(_ source: String) -> [LogicalLine] {
        let original = Array(source.utf8);
        var bytes: [UInt8] = [], physical: [Int] = [], i = 0, line = 1
        while i < original.count {
            if original[i] == 92 && i + 1 < original.count && original[i + 1] == 10 {
                i += 2;
                line += 1;
                continue
            }
            bytes.append(original[i]);
            physical.append(line);
            if original[i] == 10 {
                line += 1
            };
            i += 1
        }
        var result: [LogicalLine] = [], tokens: [Token] = [], start = 1, space = true;
        i = 0
        while i < bytes.count {
            if bytes[i] == 32 {
                i += 1;
                space = true;
                continue
            }
            if bytes[i] == 10 {
                let end = physical[i];
                result.append(LogicalLine(tokens: tokens, start: start, end: end));
                tokens = [];
                start = end + 1;
                i += 1;
                space = true;
                continue
            }
            if i + 1 < bytes.count && bytes[i] == 47 && bytes[i + 1] == 47 {
                while i < bytes.count && bytes[i] != 10 {
                    i += 1
                };
                space = true;
                continue
            }
            if i + 1 < bytes.count && bytes[i] == 47 && bytes[i + 1] == 42 {
                i += 2;
                while !(bytes[i] == 42 && bytes[i + 1] == 47) {
                    i += 1
                };
                i += 2;
                space = true;
                continue
            }
            let header = tokens.count == 2 && tokens[0].text == "#" && tokens[1].text == "include", (kind, n) = one(bytes, i, header)
            tokens.append(Token(kind, String(decoding: bytes[i..<(i + n)], as: UTF8.self), physical[i], space));
            i += n;
            space = false
        }
        if !tokens.isEmpty {
            result.append(LogicalLine(tokens: tokens, start: start, end: line))
        };
        return result
    }
}

import Foundation
struct Header {
    let name: String, rendering: String, quoted: Bool, end: Int
}
func readHeader(_ tokens: [Token], _ index: Int = 0) throws -> Header? {
    guard index < tokens.count else {
        return nil
    };
    let token = tokens[index]
    if token.kind == "string" || token.kind == "header" {
        return Header(name: String(token.text.dropFirst().dropLast()), rendering: token.text, quoted: token.kind == "string", end: index + 1)
    }
    if token.text == "<" {
        guard let end = ((index + 1)..<tokens.count).first(where: {
            tokens[$0].text == ">"
        }) else {
            throw PPError("missing terminating > character")
        }
        let name = Lexer.render(Array(tokens[(index + 1)..<end]));
        return Header(name: name, rendering: "<" + name + ">", quoted: false, end: end + 1)
    };
    return nil
}
final class ConditionalBlock {
    let kind: String, start: Position, parent: Bool
    var chosen = false, active = false, elseSeen = false, skipStart: Int?
    init(_ kind: String, _ start: Position, _ parent: Bool) {
        self.kind = kind;
        self.start = start;
        self.parent = parent
    }
}
final class Inclusion {
    let path: String, depth: Int
    var file: String, offset = 0, blocks: [ConditionalBlock] = [], segment: [Token] = []
    init(_ path: String, _ depth: Int) {
        self.path = path;
        self.depth = depth;
        file = path
    }
    var active: Bool {
        blocks.last?.active ?? true
    }
    func position(_ physical: Int) -> Position {
        Position(file: file, line: physical + offset)
    }
}
final class Preprocessor {
    let expander = Expander(), includes = IncludeManager()
    var history: [String] = [], ever: Set<String> = [], poison: Set<String> = [], saves: [String: [Macro?]] = [:]
    var output: [String] = [], tree = ["main.c"], records: [String] = [], results: [String] = [], regions: [String] = [], previous = Position(file: "main.c", line: 0)
    func diagnostic(_ position: Position, _ kind: String, _ message: String) {
        expander.diagnostic(position, kind, message)
    }
    func event(_ position: Position, _ text: String) {
        history.append("\(position): \(text)")
    }
    func poisonCheck(_ tokens: [Token], _ state: Inclusion) {
        for token in tokens where token.kind == "identifier" && poison.contains(token.text) {
            diagnostic(state.position(token.line), "error", "attempt to use poisoned \"\(token.text)\"")
        }
    }
    func unused(_ definition: Macro) {
        if definition.main && definition.expanded == 0 && definition.tested == 0 {
            diagnostic(definition.position, "warning", "macro \"\(definition.name)\" is not used")
        }
    }
    func define(_ tokens: [Token], _ position: Position, _ main: Bool) throws {
        let definition = try Definitions.parse(tokens, position, main), name = definition.name
        if let old = expander.table[name] {
            if old.identical(definition) {
                event(position, "identical " + definition.signature);
                return
            }
            unused(old);
            diagnostic(position, "warning", "\"\(name)\" redefined (previous definition at \(old.position))");
            event(position, "redefine " + definition.signature)
        } else {
            event(position, "define " + definition.signature)
        }
        expander.table[name] = definition;
        ever.insert(name)
    }
    func undef(_ tokens: [Token], _ position: Position) throws {
        let name = try Definitions.name(tokens, "undef")
        if tokens.count > 1 {
            diagnostic(position, "warning", "extra tokens at end of #undef directive")
        }
        if let old = expander.table.removeValue(forKey: name) {
            unused(old);
            event(position, "undef " + name)
        } else {
            event(position, "undef \(name) (not defined)")
        }
    }
    func marker(_ file: String, _ line: Int, _ flag: String = "") {
        output.append("# \(line) \"\(file)\"" + flag);
        previous = Position(file: file, line: line - 1)
    }
    func outputLine(_ text: String, _ physical: Int, _ state: Inclusion) {
        let position = state.position(physical)
        if previous.file == position.file && previous.line < position.line && position.line <= previous.line + 8 {
            output += Array(repeating: "", count: position.line - previous.line - 1)
        }
        else {
            marker(position.file, position.line)
        }
        output.append(text);
        previous = position;
        includes.files[state.path]!.output += 1
    }
    func flush(_ state: Inclusion) {
        poisonCheck(state.segment, state);
        let tokens = expander.expand(state.segment, state.file, state.offset);
        state.segment = []
        var i = 0
        while i < tokens.count {
            var end = i + 1;
            while end < tokens.count && tokens[end].line == tokens[i].line {
                end += 1
            };
            outputLine(Lexer.render(Array(tokens[i..<end]), true), tokens[i].line, state);
            i = end
        }
    }
    func defined(_ name: String) -> Bool {
        if let definition = expander.table[name] {
            definition.tested += 1;
            return true
        };
        return builtin(name) || name == "__has_include"
    }
    func replaceOperators(_ tokens: [Token]) throws -> [Token] {
        var result: [Token] = [], i = 0
        while i < tokens.count {
            let token = tokens[i]
            if token.kind == "identifier" && token.text == "defined" {
                i += 1;
                let parenthesis = i < tokens.count && tokens[i].text == "(";
                if parenthesis {
                    i += 1
                }
                guard i < tokens.count && tokens[i].kind == "identifier" else {
                    throw PPError("operator \"defined\" requires an identifier")
                };
                let name = tokens[i].text;
                i += 1
                if parenthesis {
                    guard i < tokens.count && tokens[i].text == ")" else {
                        throw PPError("missing ')' after \"defined\"")
                    };
                    i += 1
                }
                result.append(Token("number", defined(name) ? "1" : "0", token.line, token.space))
            } else if token.kind == "identifier" && token.text == "__has_include" {
                i += 1;
                guard i < tokens.count && tokens[i].text == "(" else {
                    throw PPError("missing '(' after \"__has_include\"")
                };
                i += 1
                guard let header = try readHeader(tokens, i), !header.name.isEmpty else {
                    throw PPError("operator \"__has_include\" requires a header-name")
                };
                i = header.end
                guard i < tokens.count && tokens[i].text == ")" else {
                    throw PPError("missing ')' after \"__has_include\" operand")
                };
                i += 1
                result.append(Token("number", IncludeManager.search(header.name, header.quoted) == nil ? "0" : "1", token.line, token.space))
            } else {
                result.append(token);
                i += 1
            }
        };
        return result
    }
    func test(_ directive: String, _ tokens: [Token], _ position: Position, _ state: Inclusion) -> (Bool, String) {
        poisonCheck(tokens, state)
        if directive != "if" && directive != "elif" {
            if tokens.isEmpty {
                diagnostic(position, "error", "no macro name given in #\(directive) directive");
                return (false, "not taken (error)")
            }
            if tokens[0].kind != "identifier" {
                diagnostic(position, "error", "macro names must be identifiers");
                return (false, "not taken (error)")
            }
            if tokens.count > 1 {
                diagnostic(position, "warning", "extra tokens at end of #\(directive) directive")
            }
            let value = defined(tokens[0].text), taken = directive == "ifndef" || directive == "elifndef" ? !value : value;
            return (taken, taken ? "taken" : "not taken")
        }
        let replaced: [Token]
        do {
            replaced = try replaceOperators(tokens)
        } catch let error as PPError {
            diagnostic(position, "error", error.message);
            return (false, "not taken (error)")
        } catch {
            preconditionFailure()
        }
        let expanded = expander.expand(replaced, state.file, state.offset), (value, diagnostics) = ExpressionParser.test(expanded, directive)
        for (kind, message) in diagnostics {
            diagnostic(position, kind, message)
        }
        let result = value.map {
            ($0 != 0 ? "taken" : "not taken") + " (value \($0))"
        } ?? "not taken (error)"
        return ((value ?? 0) != 0, result + " [" + Lexer.render(expanded, true) + "]")
    }
    func close(_ block: ConditionalBlock, _ end: Int, _ state: Inclusion) {
        if let start = block.skipStart, end >= start {
            regions.append("\(state.file):\(start + state.offset)-\(end + state.offset) lines=\(end - start + 1)");
            includes.files[state.path]!.skippedLines += end - start + 1
        };
        block.skipStart = nil
    }
    func conditional(_ directive: String, _ operands: [Token], _ line: LogicalLine, _ state: Inclusion) {
        let position = state.position(line.tokens[0].line), opening = ["if", "ifdef", "ifndef"].contains(directive), level = opening ? state.blocks.count : state.blocks.count - 1
        let result: String
        if opening {
            let block = ConditionalBlock(directive, position, state.active)
            if block.parent {
                let (taken, text) = test(directive, operands, position, state);
                block.chosen = taken;
                block.active = taken;
                if !taken {
                    block.skipStart = line.end + 1
                };
                result = text
            } else {
                result = "skipped"
            }
            state.blocks.append(block)
        } else {
            guard let block = state.blocks.last else {
                diagnostic(position, "error", "#\(directive) without #if");
                return
            }
            close(block, line.start - 1, state)
            if directive == "endif" {
                state.blocks.removeLast();
                if block.parent && !operands.isEmpty {
                    diagnostic(position, "warning", "extra tokens at end of #endif directive")
                };
                result = "closes #\(block.kind) at line \(block.start.line)"
            } else {
                if block.elseSeen {
                    diagnostic(position, "error", "#\(directive) after #else")
                }
                if directive == "else" {
                    if block.parent && !operands.isEmpty {
                        diagnostic(position, "warning", "extra tokens at end of #else directive")
                    };
                    block.elseSeen = true
                    if block.parent {
                        block.active = !block.chosen;
                        block.chosen = true;
                        result = block.active ? "taken" : "not taken"
                    } else {
                        result = "skipped"
                    }
                } else if !block.parent {
                    block.active = false;
                    result = "skipped"
                }
                else if block.chosen {
                    block.active = false;
                    result = "not evaluated"
                }
                else {
                    let (taken, text) = test(directive, operands, position, state);
                    block.active = taken;
                    if taken {
                        block.chosen = true
                    };
                    result = text
                }
                if block.parent && !block.active {
                    block.skipStart = line.end + 1
                }
            }
        }
        let rendering = "#" + directive + (operands.isEmpty ? "" : " " + Lexer.render(operands))
        records.append("\(position): " + String(repeating: " ", count: 2 * level) + rendering + " => " + result);
        results.append(result)
    }
    func include(_ operands: [Token], _ line: LogicalLine, _ state: Inclusion) throws {
        let position = state.position(line.tokens[0].line);
        var tokens = operands, header = try readHeader(tokens)
